1	// Combines local provider pricing + Artificial Analysis benchmark data into
2	// per-category recommendations.
3	
4	import { readFile, writeFile, mkdir } from "node:fs/promises";
5	import path from "node:path";
6	
7	type Provider = "copilot" | "opencode-go";
8	
9	interface Candidate {
10	  provider: Provider;
11	  model: string;
12	  priceInput: number;
13	  priceOutput: number;
14	}
15	
16	interface MappingEntry {
17	  provider: Provider;
18	  providerModel: string;
19	  aaSlug: string | null;
20	}
21	
22	interface AaModel {
23	  id: string;
24	  name: string;
25	  slug: string;
26	  evaluations: {
27	    artificial_analysis_intelligence_index?: number | null;
28	    artificial_analysis_coding_index?: number | null;
29	    artificial_analysis_agentic_index?: number | null;
30	  };
31	  performance?: {
32	    median_output_tokens_per_second?: number | null;
33	  };
34	}
35	
36	interface CategoryWeights {
37	  agenticIndex?: number;
38	  codingIndex?: number;
39	  intelligenceIndex?: number;
40	  costEfficiency?: number;
41	  speed?: number;
42	}
43	
44	interface BlacklistEntry {
45	  match: string;
46	  reason: string;
47	}
48	
49	interface ScoredCandidate {
50	  provider: Provider;
51	  model: string;
52	  aaSlug: string;
53	  score: number;
54	  breakdown: Record<string, number>;
55	  priceBlendedPer1M: number;
56	}
57	
58	const OUTPUT_OUTPUT_TO_INPUT_RATIO = 3; // assume 3 output tokens per 1 input token (typical agentic workload)
59	
60	function blendedPrice(priceInput: number, priceOutput: number): number {
61	  const totalParts = 1 + OUTPUT_OUTPUT_TO_INPUT_RATIO;
62	  return (priceInput * 1 + priceOutput * OUTPUT_OUTPUT_TO_INPUT_RATIO) / totalParts;
63	}
64	
65	// Strips variant qualifiers like " (<= 256K tokens)", " (Off-Peak)", " (Peak)" so
66	// tiered/peak pricing rows collapse to one representative candidate per base model.
67	function baseModelName(model: string): string {
68	  let stripped = model;
69	  while (/\s*\([^)]*\)\s*$/.test(stripped)) {
70	    stripped = stripped.replace(/\s*\([^)]*\)\s*$/, "").trim();
71	  }
72	  return stripped;
73	}
74	
75	function dedupeCheapest(
76	  rows: { model: string; priceInput: number; priceOutput: number }[],
77	): { model: string; priceInput: number; priceOutput: number }[] {
78	  const byBase = new Map<string, { model: string; priceInput: number; priceOutput: number }>();
79	  for (const row of rows) {
80	    const base = baseModelName(row.model);
81	    const existing = byBase.get(base);
82	    if (
83	      !existing ||
84	      blendedPrice(row.priceInput, row.priceOutput) <
85	        blendedPrice(existing.priceInput, existing.priceOutput)
86	    ) {
87	      byBase.set(base, { model: base, priceInput: row.priceInput, priceOutput: row.priceOutput });
88	    }
89	  }
90	  return [...byBase.values()];
91	}
92	
93	async function loadCandidates(): Promise<Candidate[]> {
94	  const copilotRaw = JSON.parse(
95	    await readFile(path.join("data", "copilot", "models-pricing.json"), "utf8"),
96	  );
97	  const opencodeRaw = JSON.parse(
98	    await readFile(path.join("data", "opencode-go", "models-pricing.json"), "utf8"),
99	  );
100	
101	  const copilotRows = dedupeCheapest(
102	    copilotRaw.models.map((m: { model: string; price1mInput: number; price1mOutput: number }) => ({
103	      model: m.model,
104	      priceInput: m.price1mInput,
105	      priceOutput: m.price1mOutput,
106	    })),
107	  );
108	  const opencodeRows = dedupeCheapest(
109	    opencodeRaw.models.map((m: { model: string; priceInput: number; priceOutput: number }) => ({
110	      model: m.model,
111	      priceInput: m.priceInput,
112	      priceOutput: m.priceOutput,
113	    })),
114	  );
115	
116	  return [
117	    ...copilotRows.map((r) => ({
118	      provider: "copilot" as const,
119	      model: r.model,
120	      priceInput: r.priceInput,
121	      priceOutput: r.priceOutput,
122	    })),
123	    ...opencodeRows.map((r) => ({
124	      provider: "opencode-go" as const,
125	      model: r.model,
126	      priceInput: r.priceInput,
127	      priceOutput: r.priceOutput,
128	    })),
129	  ];
130	}
131	
132	function normalize(value: number, min: number, max: number): number {
133	  if (max === min) return 1;
134	  return (value - min) / (max - min);
135	}
136	
137	export async function computeScores(): Promise<void> {
138	  const config = JSON.parse(await readFile(path.join("config", "categories.json"), "utf8"));
139	  const blacklist: BlacklistEntry[] = JSON.parse(
140	    await readFile(path.join("config", "blacklist.json"), "utf8"),
141	  );
142	  const allCandidates = await loadCandidates();
143	
144	  const candidates = allCandidates.filter((c) => {
145	    const hit = blacklist.find((b) => c.model.toLowerCase().includes(b.match.toLowerCase()));
146	    if (hit) {
147	      console.warn(`Blacklisted ${c.provider}/${c.model}: ${hit.reason}`);
148	      return false;
149	    }
150	    return true;
151	  });
152	
153	  const mapping: MappingEntry[] = JSON.parse(
154	    await readFile(path.join("config", "model-mapping.json"), "utf8"),
155	  );
156	  const aaData = JSON.parse(
157	    await readFile(path.join("data", "artificial-analysis", "language-models.json"), "utf8"),
158	  );
159	  const aaBySlug = new Map<string, AaModel>((aaData.models as AaModel[]).map((m) => [m.slug, m]));
160	
161	  const enriched: {
162	    provider: Provider;
163	    model: string;
164	    aaSlug: string;
165	    agenticIndex: number;
166	    codingIndex: number;
167	    intelligenceIndex: number;
168	    speed: number;
169	    blendedPrice1m: number;
170	  }[] = [];
171	
172	  for (const candidate of candidates) {
173	    const map = mapping.find(
174	      (m) => m.provider === candidate.provider && m.providerModel === candidate.model,
175	    );
176	    if (!map || !map.aaSlug) {
177	      console.warn(
178	        `Skipping ${candidate.provider}/${candidate.model}: no Artificial Analysis mapping.`,
179	      );
180	      continue;
181	    }
182	    const aa = aaBySlug.get(map.aaSlug);
183	    if (!aa) {
184	      console.warn(
185	        `Skipping ${candidate.provider}/${candidate.model}: aaSlug "${map.aaSlug}" not found in fetched data.`,
186	      );
187	      continue;
188	    }
189	    const {
190	      artificial_analysis_agentic_index,
191	      artificial_analysis_coding_index,
192	      artificial_analysis_intelligence_index,
193	    } = aa.evaluations;
194	    const speed = aa.performance?.median_output_tokens_per_second;
195	    if (
196	      artificial_analysis_agentic_index == null ||
197	      artificial_analysis_coding_index == null ||
198	      artificial_analysis_intelligence_index == null ||
199	      speed == null
200	    ) {
201	      console.warn(
202	        `Skipping ${candidate.provider}/${candidate.model}: incomplete benchmark data for "${map.aaSlug}".`,
203	      );
204	      continue;
205	    }
206	
207	    enriched.push({
208	      provider: candidate.provider,
209	      model: candidate.model,
210	      aaSlug: map.aaSlug,
211	      agenticIndex: artificial_analysis_agentic_index,
212	      codingIndex: artificial_analysis_coding_index,
213	      intelligenceIndex: artificial_analysis_intelligence_index,
214	      speed,
215	      blendedPrice1m: blendedPrice(candidate.priceInput, candidate.priceOutput),
216	    });
217	  }
218	
219	  const categories: Record<string, Record<Provider, ScoredCandidate[]>> = {};
220	
221	  for (const [categoryName, categoryConfig] of Object.entries(config.categories) as [
222	    string,
223	    { weights: CategoryWeights },
224	  ][]) {
225	    const weights = categoryConfig.weights;
226	    if (enriched.length === 0) {
227	      categories[categoryName] = { copilot: [], "opencode-go": [] };
228	      continue;
229	    }
230	
231	    const costEfficiencies = enriched.map((e) => 1 / e.blendedPrice1m);
232	    const ranges = {
233	      agenticIndex: [
234	        Math.min(...enriched.map((e) => e.agenticIndex)),
235	        Math.max(...enriched.map((e) => e.agenticIndex)),
236	      ],
237	      codingIndex: [
238	        Math.min(...enriched.map((e) => e.codingIndex)),
239	        Math.max(...enriched.map((e) => e.codingIndex)),
240	      ],
241	      intelligenceIndex: [
242	        Math.min(...enriched.map((e) => e.intelligenceIndex)),
243	        Math.max(...enriched.map((e) => e.intelligenceIndex)),
244	      ],
245	      speed: [Math.min(...enriched.map((e) => e.speed)), Math.max(...enriched.map((e) => e.speed))],
246	      costEfficiency: [Math.min(...costEfficiencies), Math.max(...costEfficiencies)],
247	    };
248	
249	    const scored: ScoredCandidate[] = enriched.map((e, i) => {
250	      const normAgentic = normalize(e.agenticIndex, ranges.agenticIndex[0], ranges.agenticIndex[1]);
251	      const normCoding = normalize(e.codingIndex, ranges.codingIndex[0], ranges.codingIndex[1]);
252	      const normIntelligence = normalize(
253	        e.intelligenceIndex,
254	        ranges.intelligenceIndex[0],
255	        ranges.intelligenceIndex[1],
256	      );
257	      const normSpeed = normalize(e.speed, ranges.speed[0], ranges.speed[1]);
258	      const normCost = normalize(
259	        costEfficiencies[i],
260	        ranges.costEfficiency[0],
261	        ranges.costEfficiency[1],
262	      );
263	
264	      const score =
265	        (weights.agenticIndex ?? 0) * normAgentic +
266	        (weights.codingIndex ?? 0) * normCoding +
267	        (weights.intelligenceIndex ?? 0) * normIntelligence +
268	        (weights.costEfficiency ?? 0) * normCost +
269	        (weights.speed ?? 0) * normSpeed;
270	
271	      return {
272	        provider: e.provider,
273	        model: e.model,
274	        aaSlug: e.aaSlug,
275	        score: Math.round(score * 1000) / 1000,
276	        breakdown: {
277	          agenticIndex: e.agenticIndex,
278	          codingIndex: e.codingIndex,
279	          intelligenceIndex: e.intelligenceIndex,
280	          speed: e.speed,
281	          costEfficiency: Math.round(costEfficiencies[i] * 1000) / 1000,
282	        },
283	        priceBlendedPer1M: Math.round(e.blendedPrice1m * 1000) / 1000,
284	      };
285	    });
286	
287	    scored.sort((a, b) => b.score - a.score);
288	
289	    categories[categoryName] = {
290	      copilot: scored.filter((s) => s.provider === "copilot").slice(0, config.topNPerProvider),
291	      "opencode-go": scored
292	        .filter((s) => s.provider === "opencode-go")
293	        .slice(0, config.topNPerProvider),
294	    };
295	  }
296	
297	  const outFile = path.join("data", "recommendations.json");
298	  await mkdir(path.dirname(outFile), { recursive: true });
299	  await writeFile(
300	    outFile,
301	    JSON.stringify(
302	      {
303	        generatedAt: new Date().toISOString(),
304	        topNPerProvider: config.topNPerProvider,
305	        candidatesConsidered: enriched.length,
306	        categories,
307	      },
308	      null,
309	      2,
310	    ),
311	  );
312	
313	  console.log(
314	    `Wrote recommendations for ${Object.keys(categories).length} categories (${enriched.length} scored candidates) to ${outFile}`,
315	  );
316	}
317

